"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["52890"],{30818(e){e.exports=JSON.parse('{"id":"V4-163","slug":"scope-2-emissions","term":"Scope 2 Emissions","also_known_as":[],"difficulty":"Intermediate","definition":"Scope 2 emissions are the indirect greenhouse gas emissions from the generation of electricity, steam, heating and cooling that an organisation purchases and uses.","explanation":["Under the Greenhouse Gas Protocol, Scope 2 emissions occur at the power stations or facilities that produce the energy, not at the organisation\u2019s own premises, but they are counted because the organisation\u2019s energy use causes them.","For example, an office-based company that uses electricity generated from gas or coal would report the emissions from producing that electricity as its Scope 2 emissions.","Scope 2 emissions can be calculated in two ways. The location-based method uses the average emissions of the electricity grid where the energy is used. The market-based method reflects the electricity the company has chosen to buy, such as renewable energy through contracts or certificates. Companies usually report both.","Companies can reduce Scope 2 emissions by using less energy, installing their own renewable energy and buying renewable electricity. For many service businesses, such as offices, retailers and data centres, Scope 2 emissions form a large part of their direct footprint. Critics argue that some renewable energy certificates overstate emissions reductions, prompting debate about reporting rules."],"note":"","total":1725,"prev":{"slug":"scope-1-emissions","term":"Scope 1 Emissions"},"next":{"slug":"scope-3-emissions","term":"Scope 3 Emissions"}}')}}]);